insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('859182c9-82cd-5e34-a41f-42fe537618e5', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '14270a41-7c88-5f81-ae15-86701b7aff46', 'd37cec50-e171-5815-a1b1-e8250d4a2fa1', 'A point inside a production possibility curve shows…', '["Unattainable output","Unemployed or inefficiently used resources","Productive efficiency","Economic growth"]'::jsonb, 'Output could rise without giving anything up, so resources are not fully or efficiently used.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
