insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('7d60801a-2242-5519-a7e6-ff64d32c99ab', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '14270a41-7c88-5f81-ae15-86701b7aff46', 'd37cec50-e171-5815-a1b1-e8250d4a2fa1', 'Which best describes a merit good?', '["It is a free good","Its benefits are underestimated by consumers, so it is under-consumed","It is non-rival","It harms third parties"]'::jsonb, 'Imperfect information leads to under-consumption of merit goods such as education.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
