insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('44009f34-dfb4-5d7f-a4b0-c0574d9c1ab5', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '2e481239-978a-5127-ae80-1b8e801f6f72', '95ba1fdc-7967-54ec-af65-86aa1282a718', 'Price rises from $10 to $12 and quantity demanded falls from 100 to 90. PED is…', '["−0.2","−0.5","−2","−5"]'::jsonb, '%ΔQd = −10%, %ΔP = +20%, so PED = −10 ÷ 20 = −0.5 (inelastic).') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
