insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('d009419f-865f-5134-ab23-aaddb2da6ca9', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '2e481239-978a-5127-ae80-1b8e801f6f72', '95ba1fdc-7967-54ec-af65-86aa1282a718', 'Which makes supply more price elastic?', '["Spare capacity and large inventories","Perishable products","A short time period","Factors that are hard to move between uses"]'::jsonb, 'Firms can raise output quickly when they have spare capacity or stock.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
