insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('c3c5793e-1847-581c-a51d-dd392f851ae8', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '176d8144-7473-57dc-ab8a-56a00e12efcd', '5fa3e3f1-859d-558a-a099-f6a8a8a3b1b6', 'Which is an unintended consequence of a minimum price above equilibrium?', '["A black market for buyers","A shortage","A surplus of the good","Falling producer income"]'::jsonb, 'Supply exceeds demand at the higher price; governments may have to buy and store the surplus.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
